<template>
  <SubHeader
    name="layout_builder_module"
    :label="$t('layout_builder_module')"
    :show_expiry_alert="true"
    :onSearch="false"
  />
  <!-- Action Bar: type badge + actions + save -->
  <div class="fb-action-bar">
    <div class="fb-action-bar__left">
      <q-input
        outlined
        dense
        class="layout-title-input"
        v-model="title"
        :readonly="isReadOnlyLayout || !isTitleEditable"
      >
        <template v-slot:append v-if="!isReadOnlyLayout">
          <q-icon
            class="cursor-pointer"
            @click="isTitleEditable = !isTitleEditable"
          >
            <Icon
              :icon="isTitleEditable ? 'mdi:check' : 'mdi:pencil'"
              width="18"
              height="18"
            />
          </q-icon>
        </template>
      </q-input>
      <q-chip
        :color="builderTypeColor"
        text-color="white"
        :icon="builderTypeIcon"
        :label="$t(builderTypeLabel)"
        dense
      />
    </div>

    <div class="fb-action-bar__right">
      <q-banner v-if="isReadOnlyLayout" dense class="bg-warning text-white">
        <template v-slot:avatar>
          <q-icon name="lock" color="white" size="xs" />
        </template>
        {{ $t('default_layout_readonly') }}
      </q-banner>
      <AutoGenerateDefaultLayout v-if="!layoutType && !isReadOnlyLayout" />
      <f-btn
        :label="isReadOnlyLayout ? $t('view_json') : $t('edit_json')"
        icon="code"
        @click="openJsonForm()"
      />
      <f-btn
        v-if="!isReadOnlyLayout"
        :label="$t('save')"
        icon="save"
        :loading="formBuilderStore.isSaving"
        @click="saveTemplate(true)"
      />
    </div>
  </div>

  <div class="fb-page-wrapper" style="height: calc(100vh - 110px); overflow: hidden;">
    <!-- OUTER SPLITTER: Left panel ↔️ (Middle + Right panels) -->
    <q-splitter
      :limits="[15, 40]"
      v-model="leftPanelSplitterModel"
      separator-class="left-panel-separator"
      before-class="fb-panel-left"
      after-class="fb-panel-right-outer"
      style="height: 100%;"
    >
      <!-- LEFT PANEL: Fields list -->
      <template v-slot:before>
        <div class="fb-left-panel">
          <q-tabs
            v-model="activeTab"
            dense
            indicator-color="primary"
            active-color="primary"
            class="fb-left-panel__tabs"
          >
            <q-tab
              name="general_settings"
              class="no-padding-left-right"
              icon="settings"
            />
            <q-tab
              name="form_elements"
              :label="$t('elements')"
            />
            <q-tab
              name="element_properties"
              :label="$t('properties')"
            />
          </q-tabs>

          <q-separator />

          <!-- inert, not v-if: stays readable, just not usable -->
          <div class="fb-left-panel__content" :inert="isReadOnlyLayout">
            <q-tab-panels v-model="activeTab" animated>
              <q-tab-panel name="form_elements">
                <q-expansion-item
                  expand-separator
                  default-opened
                  :label="$t('groups')"
                  group="fieldsGroup"
                  header-class="fb-expansion-header"
                >
                  <DefaultGroups />
                </q-expansion-item>

                <q-expansion-item
                  expand-separator
                  :label="$t('fields')"
                  group="fieldsGroup"
                  header-class="fb-expansion-header"
                  class="q-mb-sm"
                >
                  <DefaultElements />
                </q-expansion-item>

                <q-expansion-item
                  expand-separator
                  :label="$t('form_elements')"
                  group="fieldsGroup"
                  header-class="fb-expansion-header"
                >
                  <Elements :key="keyToUpdateComponnets" v-if="renderComponent" :isApproval="!!layoutType" />
                </q-expansion-item>
              </q-tab-panel>

              <q-tab-panel name="element_properties">
                <Properties :key="keyToUpdateComponnets" v-if="renderComponent" />
              </q-tab-panel>

              <q-tab-panel name="general_settings">
                <GeneralSettings />
              </q-tab-panel>
            </q-tab-panels>
          </div>
        </div>
      </template>

      <!-- MIDDLE + RIGHT PANELS: Existing splitter -->
      <template v-slot:after>
        <div class="full-width fb-middle-right-wrapper" style="height: 100%; overflow: hidden;">
          <q-splitter
            :limits="[30, 95]"
            v-model="formSplitterModel"
            style="height: 100%;"
            before-class="fb-panel-middle"
            after-class="fb-panel-right"
            @update:model-value="loadImageDetails"
          >
        <template v-slot:before>
          <div class="full-width fb-canvas-area">
            <FieldsDesigner
              :isPanelSection="false"
              :isReadOnly="isReadOnlyLayout"
              @clearCanvas="clearCanvas"
              @saveTemplate="saveTemplate"
              @showConnectionFromField="showConnectionFromField"
              @markTableColumns="markTableColumns"
            />
          </div>
        </template>

        <template v-slot:after>
          <div class="full-width fb-image-panel-wrapper">
            <q-splitter
              :limits="isVertexTaxVerification ? [100, 100] : [30, 94]"
              :disable="isVertexTaxVerification || !isExtenedPanel"
              v-model="splitterModel"
              horizontal
              :separator-class="isVertexTaxVerification ? 'hidden' : 'fb-splitter-separator'"
              style="height: 100%;"
              before-class="handle-scroll"
            >
              <template v-slot:before>
                <div class="fb-canvas-toolbar position-sticky t-0 l-0 z-index-3">
                  <div class="fb-canvas-toolbar__left">
                    <q-btn flat dense round icon="zoom_in" size="sm" class="fb-icon-muted" @click="zoomIn">
                      <q-tooltip>{{ $t('zoom_in') }}</q-tooltip>
                    </q-btn>
                    <q-btn flat dense round icon="zoom_out" size="sm" class="fb-icon-muted" @click="zoomOut">
                      <q-tooltip>{{ $t('zoom_out') }}</q-tooltip>
                    </q-btn>
                  </div>
                  <div class="fb-canvas-toolbar__right">
                    <q-btn v-if="!isReadOnlyLayout" flat dense round icon="upload" size="sm" class="fb-icon-muted" @click="showImages = false">
                      <q-tooltip>{{ $t('upload') }}</q-tooltip>
                    </q-btn>
                  </div>
                </div>

                <div
                  class="row form-builder-image-container"
                  v-if="showImages"
                  id="image_scrolle"
                >
                  <div
                    class="image_container overflow-scroll"
                    id="image_container"
                    style="position: relative"
                  >
                    <ImageComponent
                      v-if="formLayoutImages"
                      :pos-correction="false"
                      :width="imageWidth"
                      :cropUrl="
                        baseUrl +
                        '/' +
                        formLayoutImages[imageIndex].path +
                        '?' +
                        keyImageChange +
                        '&' +
                        tokenQueryParam
                      "
                      :markedAreasStr="markedAreasStr"
                      :connectionId="connectionId"
                      :allowMultiSelection="allowMultiSelection"
                      @restrictDrawing="restrictDrawing"
                    />
                  </div>

                  <div class="max-width-80 q-pl-sm q-pr-sm">
                    <div class="justify-center form-builder-image-container">
                      <img
                        v-for="(imageMoc, index) in formLayoutImages"
                        :data-id="index"
                        @click="loadImage(Number(index), false)"
                        :class="index === imageIndex ? 'active' : ''"
                        :key="index"
                        :src="
                          baseUrl +
                          '/' +
                          imageMoc.path +
                          '?' +
                          keyImageChange +
                          '&' +
                          tokenQueryParam
                        "
                        width="50"
                        class="cursor-pointer q-ma-sm shadow-2 solid-border-1px"
                        draggable="false"
                      />
                    </div>
                  </div>
                </div>

                <div class="full-width full-height" v-if="!showImages && !isReadOnlyLayout">
                  <import-pdf
                    @saveTemplate="saveTemplate"
                    @loadImage="loadImage"
                  />
                </div>
              </template>

              <template v-slot:after>
                <template v-if="!isVertexTaxVerification">
                  <div
                    class="fb-canvas-toolbar"
                    v-if="!isExtenedPanel"
                  >
                    <div class="fb-canvas-toolbar__left"></div>
                    <div class="fb-canvas-toolbar__right">
                      <f-toggle
                        size="xs"
                        v-model="isExtenedPanel"
                      >
                        <q-tooltip>{{ $t('activate') }} </q-tooltip>
                      </f-toggle>
                    </div>
                  </div>
                  <FieldsDesigner
                    v-if="isExtenedPanel && showPanel"
                    :isPanelSection="true"
                    :isReadOnly="isReadOnlyLayout"
                    @clearCanvas="clearCanvas"
                    @saveTemplate="saveTemplate"
                    @showConnectionFromField="showConnectionFromField"
                    @markTableColumns="markTableColumns"
                  />
                </template>
              </template>
            </q-splitter>
          </div>
        </template>
      </q-splitter>
        </div>
      </template>
    </q-splitter>
  </div>

  <!-- Dialog starts -->
  <q-dialog v-model="showJsonForm">
    <q-card class="width-800">
      <q-toolbar class="secondary-toolbar text-white">
        <q-toolbar-title>{{ isReadOnlyLayout ? $t('view_json') : $t('edit_json') }}</q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section>
        <div class="row">
          <div class="col-sm-12 col-md-12 col-lg-12">
            <div class="row">
              <q-form class="full-width">
                <div class="col-sm-12 col-md-12 col-lg-12">
                  <LayoutJsonEditor
                    ref="layoutJsonEditor"
                    :jsonData="formLayout"
                  />
                </div>
                <div
                  class="col-sm-12 col-md-12 col-lg-12 text-red-5 height-20 q-pl-md"
                ></div>

                <div class="col-sm-12 col-md-12 col-lg-12 q-pt-md">
                  <q-btn
                    v-if="!isReadOnlyLayout"
                    :label="$t('save')"
                    @click="savePastedJson()"
                    color="primary"
                    icon="done"
                    v-close-popup
                  />
                  <q-btn
                    outline
                    color="primary"
                    label="Copy Json"
                    class="float-right"
                    icon="content_copy"
                    @click="copyTemplate()"
                  />
                </div>
              </q-form>
            </div>
          </div>
        </div>
      </q-card-section>
    </q-card>
  </q-dialog>
  <!-- dialog ends -->

  <Loader />
</template>

<script lang="ts">

import { storeToRefs } from 'pinia';
import { $ } from 'src/pages/assets';
import ImportPdf from './import-pdf.vue';
import { copyToClipboard } from 'quasar';
import { defineComponent, ref } from 'vue';
import { DOC2API_URL } from 'src/pages/APIs';
import helperUtil from 'src/utils/helperUtil';
import Loader from 'src/components/Loader.vue';
import documentUtil from 'src/utils/documentUtil';
import FieldsDesigner from './fieldsDesigner.vue';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import Elements from './form_elements/Elements.vue';
import { ApiExceptions } from 'src/exceptions/index';
import { formBuilderApiService } from 'src/services';
import { isDefaultOrg, layout_types } from 'src/constants';
import { useImageAuth } from 'src/composables/useImageAuth';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import LayoutJsonEditor from 'src/components/JsonEditor.vue';
import DefaultGroups from './form_elements/DefaultGroups.vue';
import DefaultElements from './form_elements/DefaultElements.vue';
import Properties from './form_elements/properties/Properties.vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import GeneralSettings from './components/GeneralSettings/general.vue';
import { allowAbleModels } from 'src/formBuilder/formBuilderConstants';
import AutoGenerateDefaultLayout from './AutoGenerateDefaultLayout.vue';
import { formBuilderRouter } from 'src/formBuilder/utils/formBuilderRouter';
import ImageComponent from 'src/components/LayoutManagerImageComponent.vue';
import { formBuilderInputTypes } from 'src/formBuilder/formBuilderConstants';
import { notify } from 'src/components/notifications/notify';
import {
  useFormBuilderStore,
  useFormBuilderSettingsStore,
  useWorkflowsStore} from 'src/store/main';

type BuilderTypeMeta = { label: string; color: string; icon: string };

const APPROVAL_META: BuilderTypeMeta = { label: 'approval', color: 'orange', icon: 'verified' };

const BUILDER_TYPE_META: Record<string, BuilderTypeMeta> = {
  [layout_types.vertex_tax_verification]: { label: 'vertex_tax_verification', color: 'purple', icon: 'calculate' },
  [layout_types.reject]: { label: 'reject', color: 'red', icon: 'cancel' },
  [layout_types.review]: { label: 'review', color: 'blue', icon: 'rate_review' },
  [layout_types.second_approval]: { label: 'second_approval', color: 'deep-orange', icon: 'verified' },
  [layout_types.approval_v2]: APPROVAL_META,
  [layout_types.approval]: APPROVAL_META,
  [layout_types.field_validation]: { label: 'field_validation', color: 'primary', icon: 'fact_check' },
};

export default defineComponent({
  mixins: [helperMixin, documentUtil, helperUtil, displayFieldLabel],
  components: {

    AutoGenerateDefaultLayout,
    DefaultElements,
    FieldsDesigner,
    DefaultGroups,
    Properties,
    Elements,
    ImportPdf,
    SubHeader,
    ImageComponent,
    GeneralSettings,
    Loader,
    LayoutJsonEditor,
  },
  watch: {
    $route(to, from) {
      // dirty check to forcefully destory component
      // will be replaced with some quality code if some solution is found
      this.renderComponent = false;
      this.isFormBuilderMode = false;
      this.defaultFields = [];
      this.formBuilderModel = [];
      this.formBuilderConfigModel = [];
      this.clearCanvas();
      this.showImages = false;
      this.activeTab = 'form_elements';
      this.activeFieldName = '';
    },
    isExtenedPanel(val) {
      this.disableEnablePanel();
    },
  },
  data() {
    return {
      imageIndex: 0,
      templateId: ref(''),
      subDocType: ref(''),
      baseUrl: '',

      page: ref(1),
      imageHeight: 0,
      imageWidth: 200,
      connectionId: '',
      componentType: 'input',
      keyImageChange: ref(0),
      splitterModel: ref(60),
      formSplitterModel: ref(50),
      leftPanelSplitterModel: ref(22),  // Left panel vs (Middle+Right) panel
      showJsonForm: ref(false),
      showPanel: ref(false),
      markedAreasStr: '',
      allowMultiSelection: false,
      title: '',
      isTitleEditable: false,
      layoutType: '',
      // Layouts owned by the default org are system layouts: view only.
      isReadOnlyLayout: false,
    };
  },
  mounted: function () {
    this.renderComponent = true;
    this.isFormBuilderMode = true;
    this.formBuilderModel = [];
    this.formBuilderConfigModel = [];
    this.docType = this.$route.params.doc_type as string;
    this.templateId = (this.$route.query.id as string) || (this.$route.params.id as string) || '';
    this.layoutType = (this.$route.params.layout_type as string) || '';

    // This builder only edits an existing layout, so an id is required. Creation
    // happens in the Layouts overview; without an id there is nothing to edit, so
    // send the user back to the overview instead of creating a blank template.
    if (!this.templateId) {
      this.$router.replace(`/settings/doc-type-settings/${this.docType}/layouts`);
      return;
    }

    this.setSubDocType();
    this.baseUrl = DOC2API_URL;
    this.init();

    this.getWorkflows(true);

    document.addEventListener(
      'show_connection_from_react',
      this.showConnectionFromReact,
    );

    window.addEventListener('keydown', (e: any) => {
      if (e.key === 'Escape') {
        this.removeBordersFromRectangles();
        this.removeAllConnectionLines();
        this.removeExistingConfirmationOverlays();
        this.restrictDrawing();
      }
    });

    setTimeout(() => {
      const el_image_scrolle = $('.handle-scroll');
      if (el_image_scrolle) {
        el_image_scrolle.addEventListener('scroll', this.clearCanvas);
      }

      const el_field_scrolle = $('#field_scrolle');
      if (el_field_scrolle) {
        el_field_scrolle.addEventListener('scroll', this.clearCanvas);
      }
    }, 1000);

  },
  unmounted: function () {
    document.removeEventListener(
      'show_connection_from_react',
      this.showConnectionFromReact,
    );

    const el_image_scrolle = $('.handle-scroll');
    if (el_image_scrolle) {
      el_image_scrolle.removeEventListener('scroll', this.clearCanvas);
    }

    const el_field_scrolle = $('#field_scrolle');
    if (el_field_scrolle) {
      el_field_scrolle.removeEventListener('scroll', this.clearCanvas);
    }
    this.clearCanvas();
  },
  computed: {
    isVertexTaxVerification(): boolean {
      return this.layoutType === layout_types.vertex_tax_verification;
    },
    builderTypeMeta(): BuilderTypeMeta {
      if (!this.layoutType) return BUILDER_TYPE_META[layout_types.field_validation];
      return BUILDER_TYPE_META[this.layoutType] || APPROVAL_META;
    },
    builderTypeLabel(): string {
      return this.builderTypeMeta.label;
    },
    builderTypeColor(): string {
      return this.builderTypeMeta.color;
    },
    builderTypeIcon(): string {
      return this.builderTypeMeta.icon;
    },
  },
  methods: {
    async init() {
      this.formLayout = [];
      this.templateId = (this.$route.query.id as string) || (this.$route.params.id as string) || '';
      if (!this.templateId) {
        return;
      }
      await this.loadLayoutTemplateById();

      // wait is needed for medi cordinate drawing and nexttick is also not working
      // medi componnet is taking more time and this code was runing before the html render
      setTimeout(() => {
        this.initImage();
        this.prepareRectangles();
      }, 500);
    },
    async loadLayoutTemplateById() {
      let response: any;
      try {
        this.showLoading();

        response = await formBuilderApiService.getDocumentLayoutTemplateById(
          this.templateId,
        );
        if (!response) {
          throw response;
        }

        this.isReadOnlyLayout = isDefaultOrg(response.org_id);
        this.title = response.title || '';

        const saveRequired = this.applyLayoutTemplate(response, this.layoutType);

        if (this.isReadOnlyLayout) {
          this.allowAreaSelection = false;
        }

        this.disableEnablePanel();

        // A read-only layout cannot be persisted — the API answers 403.
        if (saveRequired && !this.isReadOnlyLayout) {
          this.saveTemplate(true, false);
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        return;
      } finally {
        this.hideLoading();
      }

      if (this.formLayout) {
        this.prepareLayoutModel();
      }
    },
    prepareLayoutModel() {
      for (const group of this.formLayout) {
        if (!group.fieldType) {
          group.fieldType = formBuilderInputTypes.GROUP;
        }

        // as field name and group name can be same so make group names unique
        const groupKey = this.getGroupKey(group.name);
        this.formBuilderConfigModel[groupKey] = JSON.parse(
          JSON.stringify(group),
        );
        this.formBuilderConfigModel[groupKey].rows = [];

        if (
          !this.formBuilderConfigModel[groupKey].hasOwnProperty(
            'short_cut_key_1',
          )
        ) {
          this.formBuilderConfigModel[groupKey]['short_cut_key_1'] = '';
          this.formBuilderConfigModel[groupKey]['short_cut_key_2'] = '';
        }

        if (
          !this.formBuilderConfigModel[groupKey].hasOwnProperty(
            'is_stcky_group',
          )
        ) {
          this.formBuilderConfigModel[groupKey]['is_stcky_group'] = false;
        }
      }
    },
    initImage() {
      if (!this.showImages) {
        return;
      }

      // set the width of image
      let imageElm = $('#image_container') as HTMLElement;
      this.imageWidth = imageElm.offsetWidth;
      this.imageHeight = imageElm.offsetHeight;
    },
    setSubDocType() {
      if (this.$route.query && this.$route.query.sub_doc_type) {
        this.subDocType = String(this.$route.query.sub_doc_type || '');
      }
    },
    zoomOut() {
      if (this.imageWidth > 200) {
        this.imageWidth = this.imageWidth - 100;
      }
    },
    zoomIn() {
      this.imageWidth = this.imageWidth + 100;
    },
    loadImageDetails() {
      this.initImage();
      this.showPanel = true;

      setTimeout(() => {
        this.prepareRectangles();
      }, 100);
    },
    loadImage(imageIndex: number, newImageUpload: boolean) {
      if (newImageUpload) {
        this.keyImageChange++;
      }

      this.saveMarkedAreasOfCurrentPage();
      this.imageIndex = imageIndex;
      this.page = imageIndex + 1;

      this.removeBordersFromRectangles();
      this.removeAllConnectionLines();
      this.removeExistingConfirmationOverlays();
      this.prepareRectangles();
    },
    prepareFormBuilderJson() {
      let stickyGroups: number[] = [];

      for (let [index, group] of this.formLayout.entries()) {
        const groupKey = this.getGroupKey(group.name);
        if (this.formBuilderConfigModel.hasOwnProperty(groupKey)) {
          // group.title = this.formBuilderConfigModel[groupKey].title;
          group.elementWidth =
            this.formBuilderConfigModel[groupKey].elementWidth;
          group.right_border =
            this.formBuilderConfigModel[groupKey].right_border;
          group.bottom_border =
            this.formBuilderConfigModel[groupKey].bottom_border;
          group.is_stcky_group =
            this.formBuilderConfigModel[groupKey].is_stcky_group;
          group.short_cut_key_1 =
            this.formBuilderConfigModel[groupKey].short_cut_key_1;
          group.short_cut_key_2 =
            this.formBuilderConfigModel[groupKey].short_cut_key_2;
          group.is_panel_section_group =
            this.formBuilderConfigModel[groupKey].is_panel_section_group;

          if (group.is_stcky_group) {
            stickyGroups.push(index);
          }
        }
        for (let row of group.rows) {
          // for sub groups
          if (row.fieldType == formBuilderInputTypes.SUB_GROUP) {
            row.name = this.formBuilderConfigModel[row.name].name;
            row.label = this.formBuilderConfigModel[row.name].label;
            row.elementWidth = this.formBuilderConfigModel[row.name].elementWidth;
            row.translation_key = this.formBuilderConfigModel[row.name].translation_key;

            if (row.rows.length == 0) {
              continue;
            }

            const subGroups = row.rows;

            for (let subgroup of subGroups) {
              Object.assign(
                subgroup,
                this.formBuilderConfigModel[subgroup.name],
              );
            }
            continue;
          }

          Object.assign(row, this.formBuilderConfigModel[row.name]);
        }
      }

      // move sticky groups on top
      for (const groupIndex of stickyGroups) {
        const oldItem = this.formLayout[groupIndex];
        this.formLayout.splice(groupIndex, 1);
        this.formLayout.unshift(oldItem);
      }

      this.$forceUpdate();
    },
    validateForDuplicateNameFields() {
      let uniqueFields = new Set();

      for (let [index, group] of this.formLayout.entries()) {
        for (let row of group.rows) {
          if (formBuilderInputTypes.HORIZONTAL_SEPARATOR == row.fieldType) {
            continue;
          }
          // for sub groups
          if (row.fieldType == formBuilderInputTypes.SUB_GROUP) {
            if (row.rows.length == 0) {
              continue;
            }

            const subGroups = row.rows;

            for (let subgroup of subGroups) {
              if (uniqueFields.has(subgroup.name)) {
                return { isValid: false, field: subgroup.name };
              }
              uniqueFields.add(subgroup.name);
            }
          } else if (uniqueFields.has(row.name)) {
            return {
              isValid: false,
              field:
                this.getFieldLabel(row, '') ||
                row.fieldType,
            };
          }
          uniqueFields.add(row.name);
        }
      }

      return { isValid: true, field: '' };
    },
    getLayoutJsonStr() {
      const layout_json = {
        layout: this.formLayout,
        images: this.formLayoutImages,
        proximity_tokens: this.proximityTokens,
        isExtenedPanelEnabled: this.isExtenedPanel,
      };

      Object.assign(layout_json, this.getGeneralSettingsToSave());
      return JSON.stringify(layout_json);
    },
    copyTemplate() {
      copyToClipboard(JSON.stringify(this.formLayout)).then(() => {
        notify.success('Copied!');
      });
    },
    openJsonForm() {
      this.showJsonForm = true;
    },
    savePastedJson() {
      if (this.isReadOnlyLayout) {
        return;
      }
      const strFormLayout = (this.$refs.layoutJsonEditor as any).getJson();
      if (strFormLayout) {
        this.formLayout = JSON.parse(strFormLayout);
        this.saveTemplate(false);
      }
    },
    async saveTemplate(prepareJson: boolean, success_message = true) {
      if (this.isReadOnlyLayout) {
        notify.info(this.$t('default_layout_readonly'));
        return;
      }

      // This builder edits existing layouts only — never creates. Without an id
      // there is nothing to update, so bail out.
      if (!this.templateId) {
        logError('templateId is required to save a layout');
        return;
      }

      const validationResponse = this.validateForDuplicateNameFields();
      if (!validationResponse.isValid) {
        notify.error('Duplicate key found: ' + validationResponse.field);
        return;
      }

      if (prepareJson) {
        this.saveMarkedAreasOfCurrentPage();
        this.prepareFormBuilderJson();
      }

      let response: any;
      try {
        this.formBuilderStore.isSaving = true;
        this.showLoading();

        let templateData: any = {
          doc_type_key: this.docType,
          sub_doc_type_key: this.subDocType || '',
          title: this.title || 'form builder',
          layout_json: this.getLayoutJsonStr(),
        };

        if (this.layoutType) {
          templateData.layout_type = this.layoutType;
        }

        response =
          await formBuilderApiService.updateDocumentLayoutTemplateById(
            templateData,
            this.templateId,
          );

        if (response && response.success == false) {
          throw response
        }

        if (response && success_message) {
          notify.success(this.$t('template_success_saved'));
        }

        this.templateId = response?.id || this.templateId;

        this.$forceUpdate();
        this.refreshView();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.formBuilderStore.isSaving = false;
        this.hideLoading();
      }
    },
    refreshView() {
      const url = formBuilderRouter.getFormBuilderRoute({
        doc_type_key: this.docType || '',
        layout_template_id: this.templateId || '',
        sub_doc_type_key: this.subDocType || '',
        layout_type: this.layoutType || '',
      });
      if (!url) {
        logInfo('missing params for url');
      }

      this.$router.push(url);
    },

    // ==================================code will be moved to saprate file as it is repeating in many files==================================================
    /**
     * Will remove borders from rectangles, if have any
     */
    removeBordersFromRectangles() {
      let rects: HTMLCollection = document.body.getElementsByTagName('rect');
      for (let rect of rects) {
        rect.classList.remove('svg-stroke-border');
      }
    },
    /**
     * Will remove connection lines from whole page, if have any
     */
    removeAllConnectionLines(): void {
      const connectionLineElm = $('#connection_line');
      if (connectionLineElm) {
        connectionLineElm.remove();
      }
    },
    saveMarkedAreasOfCurrentPage() {
      // empty all the alreay added areas of siries table to over come redundancy
      for (const tableName of this.documentTableNames) {
        if (this.formBuilderConfigModel.hasOwnProperty(tableName)) {
          for (const column of this.formBuilderConfigModel[tableName].columns) {
            column.coords = [];
          }
        }
      }

      for (const markedAreaObj of this.markedAreasList) {
        this.saveMarkedAreas(
          markedAreaObj.connectionId,
          markedAreaObj.markedArea,
          markedAreaObj.areaType,
        );
      }
    },
    /**
     * Replace new overlay with the old one
     */
    saveMarkedAreas(connectionId: string, coordsStr: string, areaType: string) {
      let tableInfoObj;

      exit_loops: for (const group of this.formLayout) {
        for (let row of group.rows) {
          if (
            row.fieldType === formBuilderInputTypes.EXTRACTED_TABLE &&
            areaType === 'table'
          ) {
            // 0 index contains column id
            // 1 index contains table name
            tableInfoObj = connectionId.split('__');

            if ((row.name = tableInfoObj[1])) {
              for (const column of this.formBuilderConfigModel[tableInfoObj[1]]
                .columns) {
                if (column.col_id == tableInfoObj[0]) {
                  column.coords.push({ coord: coordsStr, page: this.page });
                }
              }
              break exit_loops;
            }
          }

          if (
            !allowAbleModels.includes(row.fieldType) ||
            areaType === 'table'
          ) {
            continue;
          }

          if (row.fieldType === formBuilderInputTypes.TABLE_OF_CHECKBOXES) {
            this.formBuilderConfigModel[row.name].tableBodyRows.forEach(
              (tableBodyRow: any, bodyRowsIndex: any) => {
                tableBodyRow.forEach(
                  (tableBodyColumn: any, bodyColumnIndex: any) => {
                    if (tableBodyColumn.name === connectionId) {
                      tableBodyColumn.coords = [];
                      tableBodyColumn.page = this.page;
                      tableBodyColumn.coords.push(coordsStr);
                      return;
                    }
                  },
                );
              },
            );
          }

          if (row.name === connectionId) {
            this.formBuilderConfigModel[connectionId].page = this.page;
            this.formBuilderConfigModel[connectionId].coords = [];
            this.formBuilderConfigModel[connectionId].coords.push(coordsStr);

            row.page = this.page;
            row.coords = [];
            row.coords.push(coordsStr);
            break exit_loops;
          }
        }
      }
    },
    /**
     *
     * @param element1
     * @param element2
     * @param color
     * @param thickness
     */
    connect(
      element1: HTMLElement,
      element2: HTMLElement,
      color: string,
      thickness: number,
    ) {
      // draw a line connecting elements
      const off1 = this.getOffset(element1);
      const off2 = this.getOffset(element2);
      // bottom right
      const x1 = off1.left;
      const y1 = off1.top + off1.height / 2;
      // top right
      let x2 = off2.left + off2.width;

      const y2 = off2.top + off2.height / 2;
      // distance
      const length = Math.sqrt((x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1));
      // center
      const cx = (x1 + x2) / 2 - length / 2;
      const cy = (y1 + y2) / 2 - thickness / 2;
      // angle
      const angle = Math.atan2(y1 - y2, x1 - x2) * (180 / Math.PI);
      // Before adding line from selected record to input, lets first remove previous line
      this.removeAllConnectionLines();
      // Drawing new line
      const line = document.createElement('div');
      line.setAttribute('id', 'connection_line');
      line.style.cssText =
        'z-index: 102;padding:0px; margin:0px; height:' +
        thickness +
        'px; background-color:' +
        color +
        '; line-height:1px; position:absolute; left:' +
        cx +
        'px; top:' +
        cy +
        'px; width:' +
        length +
        'px; -moz-transform:rotate(' +
        angle +
        'deg); -webkit-transform:rotate(' +
        angle +
        'deg); -o-transform:rotate(' +
        angle +
        'deg); -ms-transform:rotate(' +
        angle +
        'deg); transform:rotate(' +
        angle +
        'deg);';
      document.body.appendChild(line);
    },
    getOffset(el: HTMLElement) {
      const rect = el.getBoundingClientRect();
      return {
        left: rect.left + window.pageXOffset,
        right: rect.right + window.pageXOffset,
        top: rect.top + window.pageYOffset,
        width: rect.width || el.offsetWidth,
        height: rect.height || el.offsetHeight,
      };
    },
    clearCanvas() {
      this.removeBordersFromRectangles();
      this.removeAllConnectionLines();
      this.removeExistingConfirmationOverlays();
    },

    getElementToConnect(fieldElement: HTMLElement) {
      this.componentType = fieldElement.getAttribute('child_type') as string;

      if (this.componentType === 'checkbox') {
        return fieldElement.querySelector('.q-checkbox__bg');
      }

      return fieldElement;
    },

    markTableColumns(columnId: string) {
      this.allowMultiSelection = true;
      this.connectionId = columnId;
      this.enableDrawing();
      this.showNotification('Please Mark Areas against this column');
    },
    showConnectionFromReact(e: any) {
      if (!e.detail || !e.detail.connectionId) {
        return;
      }

      const connectionId = e.detail.connectionId;
      let fieldElement = $('#' + connectionId) as HTMLElement;
      this.scrollInToViewCenter(fieldElement);

      this.showConnectionFromField(e.detail.connectionId);
    },
    showConnectionFromField(connectionId: string) {
      this.removeBordersFromRectangles();
      this.removeAllConnectionLines();
      this.removeExistingConfirmationOverlays();
      this.restrictDrawing();
      this.allowMultiSelection = false;
      this.connectionId = connectionId;

      let fieldElement = $('#' + connectionId) as HTMLElement;
      let pageNumber = fieldElement.getAttribute('pageno');

      let pageNumberChanged = false;
      if (pageNumber && +pageNumber !== this.page) {
        pageNumberChanged = true;
        this.page = +pageNumber;
        this.imageIndex = this.page - 1;
        this.loadImageDetails();
        this.$forceUpdate();
      }

      fieldElement.setAttribute('pageno', this.page.toString());
      // If page changed, than show connection line after 400ms, otherwise render line immediately

      setTimeout(
        () => {
          let rectElement = $('#' + connectionId + '_rect');
          if (rectElement) {
            this.scrollInToViewCenter(rectElement as HTMLElement);
          }
          setTimeout(() => {
            if (!rectElement) {
              this.componentType = fieldElement.getAttribute(
                'child_type',
              ) as string;

              let inputValue = '';

              if (this.componentType === 'checkbox') {
                inputValue = fieldElement.getAttribute('aria-checked')
                  ? 'true'
                  : '';
              } else {
                let input: HTMLInputElement | null = fieldElement.querySelector(
                  this.componentType,
                );

                if (input) {
                  inputValue = input.value;
                }
              }

              if (inputValue != '') {
                this.showNotification(
                  this.$t('SELECT_AREA_NO_COORDINATES'),
                );
              } else {
                this.showNotification(this.$t('SELECT_AREA'));
              }

              this.enableDrawing();
              return;
            }
            this.showConnection(
              connectionId,
              rectElement,
              this.getElementToConnect(fieldElement),
            );
          }, 50);
        },
        pageNumberChanged ? 400 : 100,
      );
    },
    /**
     * This connection line will perform three tasks
     * 1. Add border to rect, but we'll remove previous border first
     * 2. Add line from input to rect, but we'll remove previous line first
     * 3. Add an overlay to rect to decide whether co-ordinates are correct or not
     * @param ev
     */
    showConnection(connectionId: string, rectElement: any, fieldElement: any) {
      if (rectElement && fieldElement) {
        this.drawOverlay(connectionId, rectElement);
        // Adding border to corresponding rectangle
        rectElement.setAttribute('class', 'border');
        // Drawling line
        this.connect(
          rectElement as HTMLElement,
          fieldElement as HTMLElement,
          '#26a69a',
          2,
        );
      } else {
        alert(this.$t('NO_MAPPING_AVAILABLE'));
      }
    },
    drawOverlay(connectionId: string, rectElement: any) {
      this.connectionId = connectionId;
      this.removeExistingConfirmationOverlays();
      // parentDiv is the parent div of input that holds value
      // In order to get that value, we need to hit parent first
      // from parent, we'll get value of input
      const parentDiv: HTMLElement | null = $('#' + connectionId);
      if (!parentDiv) {
        return;
      }
      this.componentType = parentDiv.getAttribute('child_type') as string;
      // Getting input value
      let heading: string | null;

      let subHeading = '';

      if (this.componentType === 'checkbox') {
        subHeading = 'false';

        heading = 'Un-Checked';
        if (parentDiv.getAttribute('aria-checked') === 'true') {
          heading = 'Checked';
          subHeading = 'true';
        }
      } else {
        const parentDivHeading: Element | null = $('.' + connectionId);
        subHeading = parentDivHeading!.innerHTML;

        const input: HTMLInputElement | null = parentDiv.querySelector(
          this.componentType,
        );
        heading = input!.value;
      }

      const dimensionDetails = this.getOffset(rectElement);

      const divOverlay = document.createElement('div');
      divOverlay.setAttribute('id', 'confirmation_overlay');
      divOverlay.style.position = 'absolute';
      divOverlay.style.zIndex = '99999';
      divOverlay.style.left = dimensionDetails.left + 'px';
      divOverlay.style.top =
        (+dimensionDetails.top + +dimensionDetails.height + 6).toString() +
        'px';
      divOverlay.style.background = 'var(--fb-bg-tertiary)';
      divOverlay.style.color = 'var(--fb-text-muted)';
      divOverlay.style.minHeight = '80px';
      divOverlay.style.minWidth = '100px';
      divOverlay.style.maxWidth = '50%';
      divOverlay.style.textAlign = 'center';
      divOverlay.style.padding = '5px 10px 5px 10px';
      divOverlay.style.letterSpacing = '1px';
      divOverlay.style.borderRadius = '7px';
      divOverlay.style.boxShadow = `0 1px 2px rgba(0,0,0,0.07),
      0 2px 4px rgba(0,0,0,0.07),
      0 4px 8px rgba(0,0,0,0.07),
      0 8px 16px rgba(0,0,0,0.07),
      0 16px 32px rgba(0,0,0,0.07),
      0 32px 64px rgba(0,0,0,0.07);`;

      divOverlay.innerHTML = `<div><b>${heading}</b></div><div><b style='font-size: 9px'>${subHeading}</b></div>
                  <div>

                  <span class='divOverlayWrong'>
                    <span connectionId='${connectionId}' style='display: inline-block;border-radius: 50px;box-shadow: 0px 0px 2px #888;padding: 0.5em 0.6em;cursor:pointer;'>&#x2715;</span>
                  </span>
                  <span id='divOverlayCorrect'>
                    <span style='display: inline-block;border-radius: 50px;box-shadow: 0px 0px 2px #888;padding: 0.5em 0.5em;cursor:pointer;'>&#x2713;</span>
                  </span></div>`;
      document.body.appendChild(divOverlay);
      $('#divOverlayCorrect')?.addEventListener('click', (e: any) => {
        this.removeExistingConfirmationOverlays();
        this.removeBordersFromRectangles();
        this.removeAllConnectionLines();
      });

      let divOverlayWrongList =
        document.getElementsByClassName('divOverlayWrong');

      Array.from(divOverlayWrongList).forEach((element: any) => {
        element?.addEventListener('click', (e: any) => {
          this.connectionId = e.target.getAttribute('connectionId');
          if (!this.connectionId) {
            logError('connection id not found');
            return;
          }
          this.initTempFieldDelete();
          this.markedAreasStr = JSON.stringify(this.markedAreasList);
          this.removeExistingConfirmationOverlays();
          this.removeBordersFromRectangles();
          this.removeAllConnectionLines();
          this.$forceUpdate();
          this.enableDrawing();
        });
      });

      // Aligning the div overlay in center
      try {
        const overlay: HTMLElement | null = $('#confirmation_overlay');
        const overlayWidth = $('#confirmation_overlay')?.clientWidth;
        const rectWidth = dimensionDetails.width;
        const gapToDecreaseFromLeft = (+overlayWidth! - +rectWidth) / 2;
        overlay!.style.left =
          +dimensionDetails.left - +gapToDecreaseFromLeft + 'px';
      } catch (err) {}
    },
    initTempFieldDelete() {
      this.formBuilderConfigModel[this.connectionId].coords = [];
      this.clearTableOfCheckboxesCoords();
      this.markedAreasList = this.markedAreasList.filter(
        (markedAreaObj: any) =>
          markedAreaObj.connectionId !== this.connectionId,
      );
    },
    clearTableOfCheckboxesCoords() {
      if (
        this.formBuilderConfigModel[this.connectionId].fieldType !=
        formBuilderInputTypes.CHECK_BOX
      ) {
        return;
      }

      for (const group of this.formLayout) {
        for (let row of group.rows) {
          if (row.fieldType === formBuilderInputTypes.TABLE_OF_CHECKBOXES) {
            this.formBuilderConfigModel[row.name].tableBodyRows.forEach(
              (tableBodyRow: any, bodyRowsIndex: any) => {
                tableBodyRow.forEach(
                  (tableBodyColumn: any, bodyColumnIndex: any) => {
                    if (tableBodyColumn.name === this.connectionId) {
                      tableBodyColumn.coords = [];
                      tableBodyColumn.page = null;
                      return;
                    }
                  },
                );
              },
            );
          }
        }
      }
    },

    prepareRectangles() {
      this.markedAreasList = [];
      for (const group of this.formLayout) {
        for (let row of group.rows) {
          if (!this.formBuilderConfigModel.hasOwnProperty(row.name)) {
            continue;
          }

          if (row.fieldType === formBuilderInputTypes.EXTRACTED_TABLE) {
            this.prepareMarkedAreasForSerieTable(row);
            continue;
          }

          if (!allowAbleModels.includes(row.fieldType)) {
            continue;
          }

          if (row.fieldType === formBuilderInputTypes.TABLE_OF_CHECKBOXES) {
            this.prepareMarkedAreasForTableOfCheckboxes(row);
            continue;
          }

          if (!row.coords || row.coords.length < 1) {
            continue;
          }

          if (!this.formBuilderConfigModel.hasOwnProperty(row.name)) {
            continue;
          }

          if (!row.page || row.page != this.page) {
            continue;
          }

          this.addMarkedAreaToList(row);
        }
      }

      this.markedAreasStr = JSON.stringify(this.markedAreasList);
    },
    prepareMarkedAreasForTableOfCheckboxes(row: any) {
      for (let tableBodyRow of this.formBuilderConfigModel[row.name]
        .tableBodyRows) {
        for (let tableBodyColumn of tableBodyRow) {
          if (!tableBodyColumn.coords || tableBodyColumn.coords.length < 1) {
            continue;
          }

          if (
            !this.formBuilderConfigModel.hasOwnProperty(tableBodyColumn.name)
          ) {
            continue;
          }

          if (!tableBodyColumn.page || tableBodyColumn.page != this.page) {
            continue;
          }

          this.addMarkedAreaToList(tableBodyColumn);
        }
      }
    },
    prepareMarkedAreasForSerieTable(row: any) {
      for (const column of this.formBuilderConfigModel[row.name].columns) {
        if (!column.coords || column.coords.length < 1) {
          continue;
        }

        for (const coordObj of column.coords) {
          if (!coordObj.page || coordObj.page != this.page) {
            continue;
          }
          this.markedAreasList.push(
            Object.assign(
              {},
              {
                markedArea: coordObj.coord,
                connectionId: column.col_id + '__' + row.name,
                areaType: 'table',
              },
            ),
          );
        }
      }
    },
    addMarkedAreaToList(row: any) {
      const fieldObj: HTMLElement | null = $('#' + row.name);

      if (fieldObj) {
        fieldObj.setAttribute('pageno', row.page);
        this.markedAreasList.push(
          Object.assign(
            {},
            {
              markedArea: row.coords[0],
              connectionId: row.name,
              areaType: 'input',
            },
          ),
        );
      }
    },
    disableEnablePanel() {
      if (this.isVertexTaxVerification) {
        this.splitterModel = 100;
        return;
      }
      if (this.isExtenedPanel) {
        this.splitterModel = 60;
        this.showPanel = true;
      } else {
        this.splitterModel = 94;
      }
    },

    /**
     * Will allow user to draw rectangles on image when user reject div overlay
     */
    enableDrawing() {
      const draw: HTMLElement | null = $('#draw');
      draw?.classList.add('cursor-crosshair');
      draw?.classList.remove('pointer-events-none');
    },
    /**
     * Will restrict user to draw rectangles on image
     */
    restrictDrawing() {
      const draw: HTMLElement | null = $('#draw');
      draw?.classList.add('pointer-events-none');
      draw?.classList.remove('cursor-crosshair');
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    form_builder_store.$reset();
    const { getGroupKey, transformDataToV2, applyLayoutTemplate } =
      form_builder_store;
    const {
      showImages,
      activeTab,
      isFormBuilderMode,
      keyToUpdateComponnets,
      renderComponent,
      defaultFields,
      formLayout,
      documentTableNames,
      formLayoutImages,
      formBuilderModel,
      formBuilderConfigModel,
      activeFieldName,
      isExtenedPanel,
      proximityTokens,
      docType,
      markedAreasList,
      allowAreaSelection,
    } = storeToRefs(form_builder_store);

    const form_builder_settings_store = useFormBuilderSettingsStore();
    const { getGeneralSettingsToSave } = form_builder_settings_store;

    const { tokenQueryParam } = useImageAuth();
    const workflow_store = useWorkflowsStore();
    const { getWorkflows } = workflow_store;

    return {
      formBuilderStore: form_builder_store,
      getWorkflows,
      getGroupKey,
      transformDataToV2,
      applyLayoutTemplate,
      getGeneralSettingsToSave,
      docType,
      activeTab,
      showImages,
      formLayout,
      defaultFields,
      activeFieldName,
      renderComponent,
      formLayoutImages,
      formBuilderModel,
      isFormBuilderMode,
      documentTableNames,
      keyToUpdateComponnets,
      formBuilderConfigModel,
      allowAreaSelection,
      isExtenedPanel,
      proximityTokens,
      markedAreasList,
      tokenQueryParam,

      showNotification(message: string) {
        notify.info(message);
      },
    };
  },
});
</script>

